using symbol "std:io" @assert;
{ ptr a = 1, b = 2, c = 3;
  b = c; a = b; a <- 9;
  behave @assert(a == 9 && b == 9 && c == 9);
  ptr ro = b = c; c <- 12;
  behave @assert(ro == 12);
  ptr copy <- ro; copy <- 17;
  behave @assert(c == 12 && copy == 17);
  a <- b <- copy;
  behave @assert(a == 17 && b == 17 && c == 17);
};

function check(x::const i64 in O, y::i64 in O) -> void where {owner O} {
 x = y; x <- 3; {} }
{ ptr a = 1, b = 2; check(a,b); };

using symbol "std:io" @assert;
function run(count::i64) -> const i64 {
 ptr answer = -1;
 for (i in 0 .. count) { answer <- i; };
 answer
}
behave @assert(run(0) == -1 && run(3) == 2);
